import openpyxl
wb=openpyxl.load_workbook('/root/pwt1001.xlsx', read_only=True, data_only=True)
ws=wb['Data']
headers=list(next(ws.iter_rows(min_row=1, max_row=1, values_only=True)))
col_index={name:i for i,name in enumerate(headers)}
print('columns', headers[:10])
for col in ['country','year','rnna','rgdpo']:
    print(col, col_index.get(col))

rnna_by_year={}
rgdpo_by_year={}
for row in ws.iter_rows(min_row=2, values_only=True):
    if row[col_index['country']]!='Georgia':
        continue
    year=row[col_index['year']]
    rnna=row[col_index['rnna']]
    rgdpo=row[col_index['rgdpo']]
    rnna_by_year[year]=rnna
    rgdpo_by_year[year]=rgdpo

print('years', min(rnna_by_year), max(rnna_by_year))
print('sample', {y: rnna_by_year[y] for y in range(1990,1995)})
